cat > /app/output/index.html <<'HTML'
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />

  <title>Fresh Pantry - Discover Everyday Deliciousness</title>
  <meta name="title" content="Fresh Pantry - Discover Everyday Deliciousness" />
