  <meta property="twitter:title" content="Fresh Pantry - Discover Everyday Deliciousness" />
  <meta
    property="twitter:description"
    content="A warm, modern grocery destination with unique finds at everyday value."
  />
  <meta
    property="twitter:image"
    content="https://images.unsplash.com/photo-1542838132-92c53300491e?auto=format&fit=crop&w=1400&q=80"
  />

  <meta name="geo.region" content="US-IL" />
  <meta name="geo.placename" content="Chicago" />
  <meta name="geo.position" content="41.8781;-87.6298" />
  <meta name="ICBM" content="41.8781, -87.6298" />

  <script type="application/ld+json">
    {
      "@context": "https://schema.org",
      "@type": "Store",
      "name": "Fresh Pantry",
      "image": "https://images.unsplash.com/photo-1542838132-92c53300491e?auto=format&fit=crop&w=1400&q=80",
      "description": "Fresh Pantry is a neighborhood grocery brand offering unique, high-quality food products at great prices.",
      "@id": "https://www.freshpantry.com/#organization",
      "url": "https://www.freshpantry.com/",
      "telephone": "+1-312-555-0187",
      "address": {
        "@type": "PostalAddress",
        "streetAddress": "2140 N Halsted St",
        "addressLocality": "Chicago",
        "addressRegion": "IL",
        "postalCode": "60614",
        "addressCountry": "US"
      },
      "priceRange": "$$",
      "geo": {
        "@type": "GeoCoordinates",
        "latitude": 41.9228,
        "longitude": -87.6486
      },
      "openingHoursSpecification": [
        {
          "@type": "OpeningHoursSpecification",
          "dayOfWeek": [
            "Monday",
            "Tuesday",
            "Wednesday",
            "Thursday",
            "Friday",
            "Saturday",
            "Sunday"
          ],
          "opens": "08:00",
          "closes": "21:00"
        }
      ],
      "areaServed": ["Chicago", "Lincoln Park", "Wicker Park", "Lakeview"],
      "sameAs": [
        "https://www.instagram.com/",
        "https://www.facebook.com/",
        "https://www.pinterest.com/",
        "https://www.tiktok.com/"
      ]
    }
  </script>

  <script type="application/ld+json">
    {
      "@context": "https://schema.org",
      "@type": "FAQPage",
      "mainEntity": [
        {
          "@type": "Question",
          "name": "What kinds of products does Fresh Pantry offer?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Fresh Pantry offers curated pantry staples, fresh produce, frozen favorites, snacks, beverages, and dairy selections."
          }
        },
        {
          "@type": "Question",
          "name": "How do I find my nearest Fresh Pantry store?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Use the store locator by entering your zip code to view nearby stores, hours, and distances."
          }
        }
      ]
    }
  </script>

  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link
    href="https://fonts.googleapis.com/css2?family=Nunito:wght@600;700;800&family=Inter:wght@400;500;600;700&display=swap"
    rel="stylesheet"
  />

  <style>
    :root {
      --bg: #fffaf0;
      --surface: #ffffff;
      --text: #1f3d2d;
      --muted: #5d6d62;
      --primary: #2f8f52;
      --primary-dark: #247542;
      --accent: #f4b547;
      --accent-soft: #ffe6b5;
      --terracotta: #d97757;
      --shadow: 0 10px 28px rgba(41, 83, 56, 0.12);
      --radius-lg: 22px;
      --radius-md: 16px;
    }

    * { box-sizing: border-box; }

    html { scroll-behavior: smooth; }

    body {
      margin: 0;
      font-family: Inter, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
      background: linear-gradient(180deg, #fffdf8 0%, #fffaf0 55%, #fff8eb 100%);
      color: var(--text);
    }

    img { max-width: 100%; display: block; }

    .container {
      width: min(1140px, calc(100% - 2rem));
      margin: 0 auto;
    }

    h1, h2, h3, h4 {
      font-family: Nunito, Inter, sans-serif;
      letter-spacing: -0.02em;
      margin: 0;
    }

    .section-title {
      font-size: clamp(1.6rem, 3.4vw, 2.35rem);
      margin-bottom: 0.7rem;
    }

    .section-subtitle {
      color: var(--muted);
      margin: 0 0 1.6rem;
      max-width: 62ch;
      line-height: 1.65;
    }

    .header-wrap {
      position: sticky;
      top: 0;
      z-index: 30;
      backdrop-filter: blur(8px);
      background: rgba(255, 250, 240, 0.9);
      border-bottom: 1px solid rgba(47, 143, 82, 0.1);
    }

    .header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 0.95rem 0;
      gap: 1rem;
    }

    .brand {
      display: inline-flex;
      align-items: center;
      gap: 0.6rem;
      font-family: Nunito, sans-serif;
      font-size: 1.3rem;
      color: var(--text);
      text-decoration: none;
      font-weight: 800;
    }

    .brand-mark {
      width: 38px;
      height: 38px;
      border-radius: 12px;
      display: grid;
      place-items: center;
      background: linear-gradient(145deg, #63be79, #2f8f52);
      color: #fff;
      font-size: 1.2rem;
      box-shadow: var(--shadow);
    }

    .nav {
      display: flex;
      gap: 0.4rem;
      flex-wrap: wrap;
      justify-content: flex-end;
    }

    .nav a {
      text-decoration: none;
      color: var(--text);
      font-weight: 600;
      padding: 0.5rem 0.85rem;
      border-radius: 999px;
      transition: background 0.2s ease;
    }

    .nav a:hover,
    .nav a:focus-visible {
      background: var(--accent-soft);
      outline: none;
    }

    .hero {
      padding: clamp(3.3rem, 7vw, 5.8rem) 0 2.5rem;
      display: grid;
      grid-template-columns: 1.1fr 1fr;
      gap: clamp(1.2rem, 3vw, 2.4rem);
      align-items: center;
    }

    .hero h1 {
      font-size: clamp(2.2rem, 5.3vw, 4rem);
      line-height: 1.05;
      margin-bottom: 1rem;
    }

    .hero p {
      color: var(--muted);
      font-size: 1.05rem;
      line-height: 1.75;
      max-width: 52ch;
      margin: 0 0 1.6rem;
    }

    .hero-actions {
      display: flex;
      gap: 0.8rem;
      flex-wrap: wrap;
    }

    .btn {
      border: none;
      border-radius: 999px;
      padding: 0.72rem 1.18rem;
      font-size: 0.98rem;
      font-weight: 700;
      cursor: pointer;
      text-decoration: none;
      display: inline-flex;
      align-items: center;
      justify-content: center;
      transition: transform 0.2s ease, box-shadow 0.2s ease, background 0.2s ease;
    }

    .btn-primary {
      background: var(--primary);
      color: #fff;
      box-shadow: 0 8px 20px rgba(47, 143, 82, 0.25);
    }

    .btn-secondary {
      background: #fff;
      color: var(--text);
      border: 1px solid rgba(47, 143, 82, 0.25);
    }

    .btn:hover,
    .btn:focus-visible {
      transform: translateY(-2px);
      outline: none;
    }

    .hero-media {
      border-radius: var(--radius-lg);
      overflow: hidden;
      box-shadow: var(--shadow);
      min-height: 370px;
      background: #ddd;
    }

    .hero-media img {
      width: 100%;
      height: 100%;
      object-fit: cover;
    }

    section { padding: 2.6rem 0; }

    .carousel-shell {
      background: var(--surface);
      border-radius: var(--radius-lg);
      box-shadow: var(--shadow);
      padding: 1.2rem;
      position: relative;
    }

    .carousel-nav {
      position: absolute;
      top: -20px;
      right: 10px;
      display: flex;
      gap: 0.5rem;
    }

    .carousel-btn {
      width: 40px;
      height: 40px;
      border-radius: 50%;
      border: 1px solid rgba(47, 143, 82, 0.3);
      background: #fff;
      color: var(--text);
      font-size: 1.2rem;
      display: grid;
      place-items: center;
      cursor: pointer;
    }

    .carousel-track-wrap {
      overflow: hidden;
      border-radius: 14px;
    }

    .carousel-track {
      display: flex;
      gap: 1rem;
      transition: transform 0.45s ease;
      will-change: transform;
      padding: 0.4rem;
    }

    .product-card {
      min-width: calc((100% - 2rem) / 3);
      background: #fff;
      border-radius: var(--radius-md);
      overflow: hidden;
      border: 1px solid rgba(47, 143, 82, 0.12);
      box-shadow: 0 6px 18px rgba(37, 69, 51, 0.09);
    }

    .product-card img {
      width: 100%;
      height: 175px;
      object-fit: cover;
    }

    .product-card-body {
      padding: 0.9rem 0.95rem 1.05rem;
      display: flex;
      align-items: flex-start;
      justify-content: space-between;
      gap: 0.8rem;
    }

    .product-name {
      margin: 0;
      font-weight: 700;
      line-height: 1.35;
      font-size: 1rem;
    }

    .price {
      margin: 0;
      font-weight: 800;
      color: var(--primary-dark);
      white-space: nowrap;
      font-family: Nunito, sans-serif;
      font-size: 1.1rem;
    }

    .highlights {
      margin: 2rem 0 0.8rem;
      background: linear-gradient(100deg, #2f8f52 0%, #3aa862 52%, #f4b547 100%);
      border-radius: var(--radius-lg);
      padding: 1rem;
      box-shadow: var(--shadow);
    }

    .highlight-grid {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 0.9rem;
    }

    .highlight-item {
      background: rgba(255, 255, 255, 0.18);
      border: 1px solid rgba(255, 255, 255, 0.25);
      border-radius: 14px;
      padding: 0.9rem;
      color: #fff;
    }

    .highlight-item strong {
      font-family: Nunito, sans-serif;
      font-size: clamp(1.3rem, 2.8vw, 1.9rem);
      display: block;
      line-height: 1.15;
    }

    .highlight-item span {
      font-size: 0.9rem;
      opacity: 0.95;
    }

    .seasonal-grid,
    .category-grid {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 1rem;
    }

    .season-card,
    .category-card {
      border-radius: var(--radius-md);
      overflow: hidden;
      box-shadow: var(--shadow);
      background: #fff;
    }

    .season-card img,
    .category-card img {
      width: 100%;
      height: 220px;
      object-fit: cover;
    }

    .season-info {
      padding: 0.85rem 0.95rem 1rem;
    }

    .season-info h3 {
      margin: 0 0 0.35rem;
      font-size: 1.05rem;
    }

    .season-info p {
      margin: 0;
      color: var(--muted);
      font-size: 0.95rem;
    }

    .category-card {
      position: relative;
      isolation: isolate;
      transform: translateZ(0);
      transition: transform 0.24s ease;
      cursor: pointer;
      min-height: 230px;
    }

    .category-card::after {
      content: "";
      position: absolute;
      inset: 0;
      background: linear-gradient(180deg, rgba(0, 0, 0, 0.04), rgba(16, 39, 28, 0.58));
      z-index: 1;
    }

    .category-label {
      position: absolute;
      left: 1rem;
      bottom: 0.9rem;
      z-index: 2;
      color: #fff;
      font-family: Nunito, sans-serif;
      font-weight: 700;
      font-size: 1.1rem;
      padding: 0.4rem 0.65rem;
      border-radius: 999px;
      background: rgba(0, 0, 0, 0.24);
      opacity: 0.95;
      transition: transform 0.25s ease, opacity 0.25s ease;
    }

    .category-card:hover,
    .category-card:focus-within {
      transform: scale(1.03);
    }

    .category-card:hover .category-label,
    .category-card:focus-within .category-label {
      transform: translateY(-3px);
      opacity: 1;
    }

    .card-overlay {
      position: absolute;
      inset: 0;
      z-index: 2;
      display: flex;
      align-items: center;
      justify-content: center;
      background: rgba(28, 71, 49, 0.24);
      color: #fff;
      font-weight: 700;
      font-family: Nunito, sans-serif;
      letter-spacing: 0.01em;
      opacity: 0;
      transition: opacity 0.22s ease;
    }

    .category-card:hover .card-overlay,
    .category-card:focus-within .card-overlay {
      opacity: 1;
    }

    .locator,
    .newsletter {
      background: #fff;
      border-radius: var(--radius-lg);
      padding: clamp(1rem, 3vw, 1.4rem);
      box-shadow: var(--shadow);
    }

    .form-row {
      display: flex;
      gap: 0.75rem;
      flex-wrap: wrap;
      margin-bottom: 0.8rem;
    }

    .form-row input {
      flex: 1 1 240px;
      padding: 0.8rem 0.9rem;
      border-radius: 12px;
      border: 1px solid rgba(47, 143, 82, 0.27);
      font-size: 0.98rem;
      font-family: inherit;
    }

    .form-row input:focus-visible {
      outline: 2px solid rgba(47, 143, 82, 0.26);
      outline-offset: 1px;
    }

    .store-results {
      display: grid;
      gap: 0.75rem;
      margin-top: 0.7rem;
    }

    .store-card {
      border: 1px solid rgba(47, 143, 82, 0.16);
      border-radius: 12px;
      padding: 0.85rem;
      background: linear-gradient(180deg, #fff, #fffcf7);
    }

    .store-card h4 {
      margin: 0 0 0.35rem;
      font-size: 1rem;
    }

    .store-meta {
      margin: 0;
      color: var(--muted);
      line-height: 1.5;
      font-size: 0.93rem;
    }

    .newsletter-confirmation {
      margin-top: 0.7rem;
      color: var(--primary-dark);
      font-weight: 600;
      min-height: 1.2em;
    }

    footer {
      margin-top: 2rem;
      padding: 2rem 0 2.8rem;
      border-top: 1px solid rgba(47, 143, 82, 0.15);
    }

    .footer-grid {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 1.1rem;
    }

    .footer-grid h4 {
      margin: 0 0 0.5rem;
      font-size: 1rem;
    }

    .footer-grid a {
      display: inline-block;
      margin: 0.18rem 0;
      color: var(--muted);
      text-decoration: none;
      font-size: 0.92rem;
    }

    .footer-grid a:hover,
    .footer-grid a:focus-visible {
      color: var(--primary-dark);
      text-decoration: underline;
      outline: none;
    }

    .footer-note {
      margin-top: 1.1rem;
      color: var(--muted);
      font-size: 0.92rem;
    }

    @media (max-width: 980px) {
      .hero {
        grid-template-columns: 1fr;
        padding-top: 2.8rem;
      }

      .product-card { min-width: calc((100% - 1rem) / 2); }
      .seasonal-grid,
      .category-grid,
      .highlight-grid,
      .footer-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
      }
    }

    @media (max-width: 640px) {
      .container { width: min(1140px, calc(100% - 1.2rem)); }
      .product-card { min-width: 100%; }
      .seasonal-grid,
      .category-grid,
      .highlight-grid,
      .footer-grid {
        grid-template-columns: 1fr;
      }

      .nav { justify-content: flex-start; }
      .header { flex-direction: column; align-items: flex-start; }
    }
  </style>
</head>
<body>
  <div class="header-wrap">
    <header class="header container" id="top">
      <a href="index.html" class="brand" aria-label="Fresh Pantry home">
        <span class="brand-mark">🥬</span>
        <span>Fresh Pantry</span>
      </a>
      <nav class="nav" aria-label="Primary">
        <a href="#featured-products">Products</a>
        <a href="#store-locator">Our Stores</a>
        <a href="#seasonal-picks">Recipes</a>
        <a href="#footer-company">About Us</a>
      </nav>
    </header>
  </div>

  <main>
    <section class="container hero" id="hero">
      <div>
        <h1>Discover Everyday Deliciousness</h1>
        <p>
          Fresh Pantry is your neighborhood destination for unique, high-quality groceries at prices that make trying new favorites easy. Wander through curated picks, discover weekly surprises, and bring home meals that feel exciting and effortless.
        </p>
        <div class="hero-actions">
          <a class="btn btn-primary" href="#featured-products">Shop Featured Finds</a>
          <a class="btn btn-secondary" href="#store-locator">Find a Store</a>
        </div>
      </div>
      <div class="hero-media" aria-hidden="true">
        <img src="https://images.unsplash.com/photo-1542838132-92c53300491e?auto=format&fit=crop&w=1200&q=80" alt="Bright grocery aisle with produce and pantry items" />
      </div>
    </section>

    <section class="container" id="featured-products">
      <h2 class="section-title">Featured Products</h2>
      <p class="section-subtitle">Meet the crowd-favorite picks customers keep coming back for — each selected for quality, flavor, and unbeatable value.</p>

      <div class="carousel-shell">
        <div class="carousel-nav" aria-label="Featured products navigation">
          <button class="carousel-btn" id="carousel-prev" aria-label="Previous products">&#8592;</button>
          <button class="carousel-btn" id="carousel-next" aria-label="Next products">&#8594;</button>
        </div>

        <div class="carousel-track-wrap">
          <div class="carousel-track" id="product-track">
            <article class="product-card">
              <img src="https://images.unsplash.com/photo-1514996937319-344454492b37?auto=format&fit=crop&w=800&q=80" alt="Organic Maple Granola in a bowl" />
              <div class="product-card-body">
                <h3 class="product-name">Organic Maple Granola</h3>
                <p class="price">$4.99</p>
              </div>
            </article>
            <article class="product-card">
              <img src="https://images.unsplash.com/photo-1596040033229-a9821ebd058d?auto=format&fit=crop&w=800&q=80" alt="Everything But The Bagel Seasoning jar" />
              <div class="product-card-body">
                <h3 class="product-name">Everything But The Bagel Seasoning</h3>
                <p class="price">$2.49</p>
              </div>
            </article>
            <article class="product-card">
              <img src="https://images.unsplash.com/photo-1511381939415-e44015466834?auto=format&fit=crop&w=800&q=80" alt="Dark Chocolate Peanut Butter Cups" />
              <div class="product-card-body">
                <h3 class="product-name">Dark Chocolate Peanut Butter Cups</h3>
                <p class="price">$3.29</p>
              </div>
            </article>
            <article class="product-card">
              <img src="https://images.unsplash.com/photo-1611270629569-8b357cb88da9?auto=format&fit=crop&w=800&q=80" alt="Cauliflower Gnocchi in skillet" />
              <div class="product-card-body">
                <h3 class="product-name">Cauliflower Gnocchi</h3>
                <p class="price">$2.99</p>
              </div>
            </article>
            <article class="product-card">
              <img src="https://images.unsplash.com/photo-1604908176997-4318b3f03eea?auto=format&fit=crop&w=800&q=80" alt="Mandarin Orange Chicken plated" />
              <div class="product-card-body">
                <h3 class="product-name">Mandarin Orange Chicken</h3>
                <p class="price">$5.79</p>
              </div>
            </article>
          </div>
        </div>
      </div>

      <div class="highlights" aria-label="Brand highlights">
        <div class="highlight-grid">
          <div class="highlight-item">
            <strong>500+</strong>
            <span>Stores Nationwide</span>
          </div>
          <div class="highlight-item">
            <strong>4,000+</strong>
            <span>Unique Products</span>
          </div>
          <div class="highlight-item">
            <strong>80%</strong>
            <span>Private Label Items</span>
          </div>
          <div class="highlight-item">
            <strong>New Weekly</strong>
            <span>New Items Every Week</span>
          </div>
        </div>
      </div>
    </section>

    <section class="container" id="seasonal-picks">
      <h2 class="section-title">Seasonal Picks</h2>
      <p class="section-subtitle">Celebrate the moment with limited-time flavors and cozy kitchen staples curated for this season.</p>
      <div class="seasonal-grid">
        <article class="season-card">
          <img src="https://images.unsplash.com/photo-1615485737651-9a5f18d55757?auto=format&fit=crop&w=900&q=80" alt="Butternut squash and autumn vegetables" />
          <div class="season-info">
            <h3>Harvest Kitchen</h3>
            <p>Comfort-forward produce and savory pantry essentials for warm weeknight meals.</p>
          </div>
        </article>
        <article class="season-card">
          <img src="https://images.unsplash.com/photo-1512621776951-a57141f2eefd?auto=format&fit=crop&w=900&q=80" alt="Colorful seasonal salad ingredients" />
          <div class="season-info">
            <h3>Color Pop Salads</h3>
            <p>Fresh greens, bright toppings, and dressings that make every bowl feel exciting.</p>
          </div>
        </article>
        <article class="season-card">
          <img src="https://images.unsplash.com/photo-1606787366850-de6330128bfc?auto=format&fit=crop&w=900&q=80" alt="Baskets filled with pantry and snack items" />
          <div class="season-info">
            <h3>Snack Board Night</h3>
            <p>Cheeses, crackers, dips, and sweet pairings for effortless gathering spreads.</p>
