  <script>
    (() => {
      const track = document.getElementById('product-track');
      const prevBtn = document.getElementById('carousel-prev');
      const nextBtn = document.getElementById('carousel-next');
      const cards = Array.from(track.children);

      let currentIndex = 0;
      let cardsPerView = getCardsPerView();

      function getCardsPerView() {
        if (window.innerWidth <= 640) return 1;
        if (window.innerWidth <= 980) return 2;
        return 3;
      }

      function maxIndex() {
        return Math.max(0, cards.length - cardsPerView);
      }

      function updateCarousel() {
        cardsPerView = getCardsPerView();
        currentIndex = Math.min(currentIndex, maxIndex());
        const offset = cards[currentIndex].offsetLeft - cards[0].offsetLeft;
        track.style.transform = `translateX(${-offset}px)`;
      }

      prevBtn.addEventListener('click', () => {
        currentIndex = Math.max(0, currentIndex - 1);
        updateCarousel();
      });

      nextBtn.addEventListener('click', () => {
        currentIndex = Math.min(maxIndex(), currentIndex + 1);
        updateCarousel();
      });

      window.addEventListener('resize', updateCarousel);
      updateCarousel();

      const storeForm = document.getElementById('store-form');
      const zipInput = document.getElementById('zip-input');
      const storeResults = document.getElementById('store-results');

      const sampleStores = [
        {
          name: 'Fresh Pantry — Lincoln Park',
          address: '2140 N. Halsted St, Chicago, IL 60614',
          hours: '8am – 9pm Daily',
          distance: '0.8 mi'
        },
        {
          name: 'Fresh Pantry — Wicker Park',
          address: '1840 W. North Ave, Chicago, IL 60622',
          hours: '8am – 9pm Daily',
          distance: '1.4 mi'
        },
        {
          name: 'Fresh Pantry — Lakeview',
          address: '3745 N. Lincoln Ave, Chicago, IL 60613',
          hours: '8am – 9pm Daily',
          distance: '2.1 mi'
        }
      ];

      function renderStores() {
        storeResults.innerHTML = '';
        sampleStores.forEach((store) => {
          const card = document.createElement('article');
          card.className = 'store-card';
          card.innerHTML = `
            <h4>${store.name}</h4>
            <p class="store-meta">${store.address}<br>${store.hours} · ${store.distance}</p>
          `;
          storeResults.appendChild(card);
        });
      }

      storeForm.addEventListener('submit', (event) => {
        event.preventDefault();
        const zip = zipInput.value.trim();
        if (!/^\d{5}$/.test(zip)) {
          storeResults.innerHTML = '<p class="store-meta">Please enter a valid 5-digit zip code.</p>';
          return;
        }
        renderStores();
      });

      const newsletterForm = document.getElementById('newsletter-form');
      const newsletterEmail = document.getElementById('newsletter-email');
      const newsletterConfirmation = document.getElementById('newsletter-confirmation');

      newsletterForm.addEventListener('submit', (event) => {
        event.preventDefault();
        const email = newsletterEmail.value.trim();
        const isValidEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);

        if (!isValidEmail) {
          newsletterConfirmation.textContent = 'Please enter a valid email address to subscribe.';
          return;
        }

        newsletterConfirmation.textContent = 'Thanks for subscribing! Check your inbox for a welcome treat.';
        newsletterForm.reset();
      });
    })();
  </script>
</body>
